// Brute-force: score = sum over sphinxes of (1 + bonus(E)) where
// E = distinct types counted under some policy, bonus = E>k ? 2*(E-k) : c
const ex = [
  [["s","c","o"],2],
  [["s","c","o","z","h"],3],
  [["s","c","o","z","h","y"],5],
  [["s","s","c","o"],4],
  [["s","s","c","o","z"],6],
  [["s","y"],2],
  [["s","u1","u3","c"],2],
  [["s","u1","u2","u3","y","o","c"],3],
  [["c","o","z"],0],
  [["s","c","c","c","o","o"],2],
];
const base=(m)=>m.startsWith("u")?"u":m;         // UW variants collapse
const baseSplit=(m)=>m;                           // UW variants distinct
for (const uw of [base,baseSplit])
for (const policy of ["all","exclSelfCard","exclAllSphinx"])
for (const k of [1,2,3,4])
for (const c of [0,1,2])
for (const perSphinxBonus of [true,false]) {
  let ok=true;
  for (const [army,want] of ex) {
    const sph=army.filter(m=>m==="s").length;
    let total=0;
    if(sph===0){ if(want!==0) ok=false; continue; }
    let bonusSum=0;
    for(let i=0;i<sph;i++){
      let types;
      if(policy==="all") types=new Set(army.map(uw));
      else if(policy==="exclAllSphinx") types=new Set(army.filter(m=>m!=="s").map(uw));
      else { const a=[...army]; a.splice(a.indexOf("s"),1); types=new Set(a.map(uw)); }
      const E=types.size;
      bonusSum += E>k ? 2*(E-k) : c;
      if(!perSphinxBonus) break;
    }
    total = sph*1 + (perSphinxBonus?bonusSum:bonusSum);
    if(total!==want) ok=false;
  }
  if(ok) console.log("FIT:",uw===base?"uw-collapsed":"uw-split",policy,"k="+k,"c="+c,"perSphinx="+perSphinxBonus);
}
console.log("search done");
EOF
